--- index.html
+++ index.html
@@ -17,4 +17,19 @@
 <section class="center"><div class="globe-wrap"><div id="globe"></div><div class="map-label"><div class="eyebrow">Earth · Population layer</div><strong>National population · proportional markers</strong></div><div class="controls"><button class="icon-btn" id="zoomIn" aria-label="Zoom in">＋</button><button class="icon-btn" id="zoomOut" aria-label="Zoom out">−</button><button class="icon-btn" id="pause" aria-label="Pause rotation">Ⅱ</button></div><div class="legend"><div class="legend-title">Marker size = population</div><div class="legend-scale"><span>LOW</span><div class="legend-dots"><i></i><i></i><i></i></div><span>HIGH</span></div></div><div class="map-footer">COUNTRY-LEVEL AGGREGATES<br>NOT INDIVIDUAL LOCATIONS</div><div class="status" id="status">Loading globe and source data…</div></div></section>
 <aside class="side right"><div class="eyebrow">Explore · learn</div><div id="countryDetail" class="country-panel"><div class="stat-label">Select a marker</div><div class="country-placeholder">Tap a glowing marker or choose a country to see its reported population.</div></div><div class="quiz"><div class="quiz-head"><div class="section-title">Population challenge</div><div class="score">SCORE <span id="score">0</span></div></div><div class="quiz-card"><p id="question">Which country has the larger population?</p><div class="quiz-choices" id="choices"></div><div class="quiz-msg" id="quizMsg">Pick a country to start.</div><button class="next-btn" id="next">New comparison ↗</button></div></div><div class="source-box">Figures come from the World Bank indicator <b>SP.POP.TOTL</b>. Latest available annual observation is shown for each country. Boundaries are for visualization only.</div></aside>
 </main></div>
 <script src="https://unpkg.com/globe.gl"></script><script src="https://unpkg.com/d3-geo@3"></script><script>
+(()=>{'use strict';
+const $=id=>document.getElementById(id),fmt=new Intl.NumberFormat('en-US');let globe,countries=[],score=0,round=null,rotation=true;
+const status=(text,show=true)=>{$('status').textContent=text;$('status').style.display=show?'block':'none'};
+function short(n){if(n>=1e9)return(n/1e9).toFixed(2)+'B';if(n>=1e6)return(n/1e6).toFixed(1)+'M';return fmt.format(n)}
+function showCountry(c){if(!c)return;$('countryDetail').innerHTML='<div class="stat-label">COUNTRY · '+c.year+' ESTIMATE</div><h2>'+esc(c.name)+'</h2><div class="big">'+short(c.population)+'</div><p>people · national aggregate<br>World Bank indicator SP.POP.TOTL</p>';if(globe)globe.pointOfView({lat:c.lat,lng:c.lng,altitude:1.55},900)}
+function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
+function drawList(filter=''){const found=countries.filter(c=>c.name.toLowerCase().includes(filter.toLowerCase())).slice(0,filter?80:30);$('countryList').innerHTML=found.map((c,i)=>'<div class="country-row" data-code="'+c.code+'"><span class="country-rank">'+String(c.rank).padStart(2,'0')+'</span><span class="country-name">'+esc(c.name)+'</span><span class="country-pop">'+short(c.population)+'</span></div>').join('');$('countryList').querySelectorAll('.country-row').forEach(el=>el.onclick=()=>showCountry(countries.find(c=>c.code===el.dataset.code)))}
+function setRound(){if(countries.length<2)return;let a,b;do{a=countries[Math.floor(Math.random()*countries.length)];b=countries[Math.floor(Math.random()*countries.length)]}while(a===b||Math.abs(a.rank-b.rank)<3);round={a,b,answered:false};$('choices').innerHTML=[a,b].sort(()=>Math.random()-.5).map(c=>'<button class="choice" data-code="'+c.code+'">'+esc(c.name)+'<span>?</span></button>').join('');$('quizMsg').textContent='Choose the more populous country.';$('choices').querySelectorAll('button').forEach(btn=>btn.onclick=()=>answer(btn.dataset.code))}
+function answer(code){if(!round||round.answered)return;round.answered=true;const winner=round.a.population>round.b.population?round.a:round.b,correct=code===winner.code;$('choices').querySelectorAll('button').forEach(b=>{b.disabled=true;const c=countries.find(x=>x.code===b.dataset.code);b.querySelector('span').textContent=fmt.format(c.population);if(c.code===winner.code)b.classList.add('correct');else if(c.code===code)b.classList.add('wrong')});if(correct){score++;$('score').textContent=score;$('quizMsg').textContent='Correct — '+winner.name+' has more people.'}else $('quizMsg').textContent='Not quite. '+winner.name+' has more people.'}
+async function load(){try{if(!window.Globe||!window.d3){throw Error('Globe library did not load. Check your connection and refresh.')}
+const worldUrl='https://raw.githubusercontent.com/datasets/geo-countries/master/data/countries.geojson',popUrl='https://api.worldbank.org/v2/country/all/indicator/SP.POP.TOTL?format=json&per_page=20000&date=2020:2024';
+const [geoRes,popRes]=await Promise.all([fetch(worldUrl),fetch(popUrl)]);if(!geoRes.ok||!popRes.ok)throw Error('Could not reach an official data source. Check your connection and reload.');const [geo,raw]=await Promise.all([geoRes.json(),popRes.json()]);
+if(!Array.isArray(raw[1]))throw Error('Population source returned no observations. Please reload later.');const pops=new Map();for(const d of raw[1]){const code=d.countryiso3code,n=Number(d.value),year=Number(d.date);if(code&&code.length===3&&Number.isFinite(n)&&n>0){const prev=pops.get(code);if(!prev||year>prev.year)pops.set(code,{population:n,year})}}
+for(const f of geo.features){const p=f.properties||{},code=p['ISO3166-1-Alpha-3']||p.ISO_A3||p.iso_a3,datum=pops.get(code),name=p.name||p.ADMIN||p.NAME;if(!code||!name||!datum||!f.geometry)continue;const center=d3.geoCentroid(f);if(!center||!Number.isFinite(center[0]))continue;countries.push({code,name,population:datum.population,year:datum.year,lng:center[0],lat:center[1],geometry:f.geometry,feature:f})}
+countries.sort((a,b)=>b.population-a.population);countries.forEach((c,i)=>c.rank=i+1);if(!countries.length)throw Error('No matching country records were returned by the sources.');

input.newString:
countries.sort((a,b)=>b.population-a.population);countries.forEach((c,i)=>c.rank=i+1);if(!countries.length)throw Error('No matching country records were returned by the sources.');
const total=countries.reduce((sum,c)=>sum+c.population,0);$('totalPop').textContent=short(total);$('statFoot').textContent='mapped across '+countries.length+' countries · latest available estimates';const years=[...new Set(countries.map(c=>c.year))];$('dateLabel').textContent='SOURCE YEARS · '+Math.min(...years)+'–'+Math.max(...years);drawList();setRound();
const max=countries[0].population;
globe=Globe()(document.getElementById('globe')).backgroundColor('rgba(0,0,0,0)').globeImageUrl('https://unpkg.com/three-globe/example/img/earth-night.jpg').bumpImageUrl('https://unpkg.com/three-globe/example/img/earth-topology.png').showAtmosphere(true).atmosphereColor('#6fbd91').atmosphereAltitude(.17).polygonsData(geo.features.filter(f=>countries.some(c=>c.feature===f))).polygonCapColor(f=>{const c=countries.find(x=>x.feature===f);return c?'rgba(130,190,135,0.12)':'rgba(55,83,70,0.12)'}).polygonSideColor(()=> 'rgba(25,57,46,0.38)').polygonStrokeColor(()=> 'rgba(148,185,151,0.32)').polygonAltitude(.005).polygonLabel(f=>{const c=countries.find(x=>x.feature===f);return c?'<div class="tooltip"><b>'+esc(c.name)+'</b><br>'+short(c.population)+' people · '+c.year+'</div>':''}).onPolygonClick(f=>showCountry(countries.find(c=>c.feature===f))).pointsData(countries).pointLat(d=>d.lat).pointLng(d=>d.lng).pointColor(()=> '#ff604b').pointAltitude(d=>.008+Math.sqrt(d.population/max)*.045).pointRadius(d=>.018+Math.sqrt(d.population/max)*.22).pointResolution(8).pointLabel(d=>'<div class="tooltip"><b>'+esc(d.name)+'</b><br>'+short(d.population)+' people · '+d.year</div>').onPointClick(showCountry).pointsMerge(false).enablePointerInteraction(true).polygonsTransitionDuration(500);
globe.pointOfView({lat:18,lng:8,altitude:2.1});globe.controls().autoRotate=true;globe.controls().autoRotateSpeed=.35;globe.controls().enableDamping=true;status('',false);$('statFoot').textContent='country aggregates · '+countries.length+' reporting areas';
}catch(err){console.error(err);status(err.message||'Unable to load public sources.');$('totalPop').textContent='Unavailable';$('statFoot').textContent='No values are fabricated or substituted.'}}
$('search').addEventListener('input',e=>drawList(e.target.value));$('next').onclick=setRound;$('zoomIn').onclick=()=>{if(globe){const p=globe.pointOfView();globe.pointOfView({...p,altitude:Math.max(.7,p.altitude*.76)},450)}};$('zoomOut').onclick=()=>{if(globe){const p=globe.pointOfView();globe.pointOfView({...p,altitude:Math.min(4,p.altitude*1.3)},450)}};$('pause').onclick=e=>{if(globe){rotation=!rotation;globe.controls().autoRotate=rotation;e.currentTarget.textContent=rotation?'Ⅱ':'▶';e.currentTarget.setAttribute('aria-label',rotation?'Pause rotation':'Resume rotation')}};load();
})();
</script></body></html>

